/**
 * Blog registry — the computed catalog of all 778 reference blog routes.
 *
 * The raw slug list and the curated classification sets live in
 * blog-registry-data.ts (generated by scripts/gen-blog-registry.py from the
 * reference sitemap). Everything here is DERIVED from that data: families,
 * categories, display titles, the catalog order, and pagination math. The
 * census is computed at module load — never hand-set — so the numbers the
 * pages and tests quote cannot drift from the data they describe.
 *
 * Category computation for not-written rows mirrors the reference's
 * taxonomy by topic keyword; game-guides and off-scope rows are
 * deliberately UNCATEGORIZED, which matches the reference's live pages
 * (verified 2026-10-30: game-guide articles carry no category badge and
 * the twelve category hubs list only core-3D articles).
 */
import type { BlogArticleDef, BlogCategory, BlogEntry, BlogFamily } from "./blog-types";
import { BLOG_ARTICLES_A } from "./blog-content-a";
import { BLOG_ARTICLES_B } from "./blog-content-b";
import { BLOG_ARTICLES_C } from "./blog-content-c";
import { BLOG_ARTICLES_D } from "./blog-content-d";
import { BLOG_ARTICLES_E } from "./blog-content-e";
import {
  CORE_3D_SLUGS,
  OFF_SCOPE_SLUGS,
  REFERENCE_BLOG_SLUGS,
  REFERENCE_NEWS_SLUGS,
  WRITTEN_SLUGS,
} from "./blog-registry-data";

/** All 55 written articles, one array, slug-unique. */
export const BLOG_ARTICLES: BlogArticleDef[] = [
  ...BLOG_ARTICLES_A,
  ...BLOG_ARTICLES_B,
  ...BLOG_ARTICLES_C,
  ...BLOG_ARTICLES_D,
  ...BLOG_ARTICLES_E,
];

const WRITTEN_BY_SLUG = new Map(BLOG_ARTICLES.map((a) => [a.slug, a]));

// -- invariants: the written set must exactly match the curated data ------
const writtenSlugs = new Set(WRITTEN_SLUGS);
const articleSlugs = new Set(BLOG_ARTICLES.map((a) => a.slug));
if (writtenSlugs.size !== articleSlugs.size || [...writtenSlugs].some((s) => !articleSlugs.has(s))) {
  throw new Error("blog registry: WRITTEN_SLUGS and BLOG_ARTICLES disagree");
}

// -- family computation ----------------------------------------------------
const CORE_SET = new Set(CORE_3D_SLUGS);
const NEWS_SET = new Set(REFERENCE_NEWS_SLUGS);
const OFF_SET = new Set(OFF_SCOPE_SLUGS);

/** The computed family of a reference slug (curated sets, then default). */
export function blogFamily(slug: string): BlogFamily {
  if (writtenSlugs.has(slug)) return "written";
  if (NEWS_SET.has(slug)) return "reference-news";
  if (OFF_SET.has(slug)) return "off-scope";
  if (CORE_SET.has(slug)) return "core-filler";
  return "game-filler";
}

// -- category computation for not-written rows ----------------------------

/** Keyword rules for core/reference rows, first match wins. */
const CATEGORY_RULES: [BlogCategory, RegExp][] = [
  ["3d-printing", /print|stl|filament|resin|pla\b|lithophane|slicing|3mf|miniatures?/],
  ["ai-texturing", /texture|hdri|pbr|uv-|material|texturing/],
  ["xr", /(^|[^a-z])(vr|ar|webxr|vision-pro|vrchat)([^a-z]|$)|^ar-|usdz/],
  ["animation", /animat|rig|rigging|avatar|metahuman|vtuber|blendshape/],
  ["image-to-3d", /image-to|photo|sketch|drawing|vector|svg|video-to|photogrammetry/],
  ["text-to-3d", /text-to|^ai-3d-prompts/],
  ["prompt-guide", /prompt/],
  ["game-development", /game|unity|unreal|godot|roblox|engine|indie/],
  ["comparisons", /-vs-|alternative|review|best-|^comparing/],
];

/** Category for a not-written core/reference row; undefined for the rest. */
export function computedBlogCategory(slug: string): BlogCategory | undefined {
  const family = blogFamily(slug);
  if (family !== "core-filler" && family !== "reference-news") return undefined;
  if (family === "reference-news") return "news";
  for (const [cat, re] of CATEGORY_RULES) {
    if (re.test(slug)) return cat;
  }
  return "insights";
}

// -- display titles for not-written rows ----------------------------------

const TITLE_MINOR = new Set([
  "a", "an", "and", "as", "at", "but", "by", "for", "in", "nor", "of", "on", "or",
  "per", "so", "the", "to", "vs", "via", "with", "from", "into", "onto",
]);

/** Topic title derived from a slug — title case with minor words lowered. */
export function blogTopicTitle(slug: string): string {
  const words = slug.split("-").filter(Boolean);
  return words
    .map((w, i) => {
      if (/^\d+$/.test(w)) return w;
      const lower = w.toLowerCase();
      if (i > 0 && TITLE_MINOR.has(lower)) return lower;
      return lower.charAt(0).toUpperCase() + lower.slice(1);
    })
    .join(" ");
}

// -- the catalog -----------------------------------------------------------

function entryFor(slug: string): BlogEntry {
  const family = blogFamily(slug);
  const article = WRITTEN_BY_SLUG.get(slug);
  return {
    slug,
    family,
    ...(article ? { article } : {}),
    ...(family === "written"
      ? {}
      : family === "game-filler" || family === "off-scope"
        ? {}
        : { category: computedBlogCategory(slug) }),
    title: article?.title ?? blogTopicTitle(slug),
  };
}

const FAMILY_ORDER: Record<BlogFamily, number> = {
  written: 0,
  "reference-news": 1,
  "core-filler": 2,
  "off-scope": 3,
  "game-filler": 4,
};

/**
 * The full catalog in display order: written articles newest-first (date
 * desc, slug as tiebreak), then the reference's news posts, the core 3D
 * topics, the off-scope stragglers, and the game-guide farm — each tail
 * group alphabetical. Our articles first because they are the ones a
 * reader can actually read; the rest is the honest catalog.
 */
export const BLOG_CATALOG: BlogEntry[] = REFERENCE_BLOG_SLUGS.map(entryFor).sort((a, b) => {
  const fa = FAMILY_ORDER[a.family];
  const fb = FAMILY_ORDER[b.family];
  if (fa !== fb) return fa - fb;
  if (a.family === "written" && b.family === "written") {
    const da = a.article?.date ?? "";
    const db = b.article?.date ?? "";
    if (da !== db) return da < db ? 1 : -1;
  }
  return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
});

// -- the census (computed, never hand-set) ---------------------------------

export const BLOG_CENSUS = {
  total: BLOG_CATALOG.length,
  written: BLOG_CATALOG.filter((e) => e.family === "written").length,
  referenceNews: BLOG_CATALOG.filter((e) => e.family === "reference-news").length,
  coreFiller: BLOG_CATALOG.filter((e) => e.family === "core-filler").length,
  offScope: BLOG_CATALOG.filter((e) => e.family === "off-scope").length,
  gameFiller: BLOG_CATALOG.filter((e) => e.family === "game-filler").length,
} as const;

/** Routes the sitemap must carry: /blog plus every article route. */
export const BLOG_SITEMAP_LOCS: string[] = ["/blog", ...BLOG_CATALOG.map((e) => `/blog/${e.slug}`)];

// -- pagination ------------------------------------------------------------

/** Articles per pagination page (the reference pages 778 across 20 pages). */
export const BLOG_PAGE_SIZE = 40;

/** Total pagination pages covering the catalog at BLOG_PAGE_SIZE. */
export const BLOG_PAGE_COUNT = Math.ceil(BLOG_CATALOG.length / BLOG_PAGE_SIZE);

/** The catalog slice for a 1-based page number. */
export function blogPage(page: number): BlogEntry[] {
  if (page < 1 || page > BLOG_PAGE_COUNT) return [];
  return BLOG_CATALOG.slice((page - 1) * BLOG_PAGE_SIZE, page * BLOG_PAGE_SIZE);
}
